shell_commands:
/usr/bin/zsh -lc "cat > src/orchestration/onErrorCause.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

async function rejectFromProvider(reason: unknown): Promise<{rejection: unknown; seen: Error[]}> {
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw reason;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test assistant'}), undefined, {
    hooks: {onError: async (_session, error) => void seen.push(error)},
  });

  const rejection = await orchestrator.processMessage(session).then(
    () => 'resolved',
    (error: unknown) => error
  );
  return {rejection, seen};
}

// specs/hal-engine-config-hooks/spec.md#8
it('preserves a string rejection as the onError cause and caller rejection', async () => {
  const reason = 'string boom';
  const {rejection, seen} = await rejectFromProvider(reason);

  expect({
    rejection,
    calls: seen.length,
    isError: seen[0] instanceof Error,
    message: seen[0]?.message,
    cause: seen[0]?.cause,
  }).toEqual({rejection: reason, calls: 1, isError: true, message: reason, cause: reason});
});

// specs/hal-engine-config-hooks/spec.md#8
it('reports a rejection even when converting its value to a string throws', async () => {
  const reason = {
    toString: () => {
      throw new Error('string conversion failed');
    },
  };
  const {rejection, seen} = await rejectFromProvider(reason);

  expect({
    sameRejection: rejection === reason,
    calls: seen.length,
    isError: seen[0] instanceof Error,
    cause: seen[0]?.cause,
  }).toEqual({sameRejection: true, calls: 1, isError: true, cause: reason});
});

// specs/hal-engine-config-hooks/spec.md#8
it('preserves an undefined rejection as the onError cause and caller rejection', async () => {
  const {rejection, seen} = await rejectFromProvider(undefined);

  expect({
    rejection,
    calls: seen.length,
    isError: seen[0] instanceof Error,
    hasCause: Object.hasOwn(seen[0]"'!, '"'cause'),
    cause: seen[0]?.cause,
  }).toEqual({rejection: undefined, calls: 1, isError: true, hasCause: true, cause: undefined});
});
EOF"
